  ('d92fb7fc-a901-5798-acb5-0dde1620f4e4', '3b3029e8-8048-5c9b-a9bd-b75915f5547e', 'Army', 'enlisted', '91A', null, 'assignments', 'E-1..E-4', null, 'Private, Specialist/Corporal — Operational assignments', 'Chapter 4. Military occupational specialty 91A M1 Abrams Tank System', 'Abrams Tank System Maintainer', '168eb4c51baf75ad6b0899f2ec703c6fc9bb25414cfe702dd6ec2b0f46d989d8', 10, 10, null, 87, null, null, false, null),
  ('506d2e34-30aa-5066-9b51-cdb2dc11f213', '3b3029e8-8048-5c9b-a9bd-b75915f5547e', 'Army', 'enlisted', '91A', null, 'development', 'E-1..E-4', null, 'Private, Specialist/Corporal — Institutional assignments', 'Chapter 4. Military occupational specialty 91A M1 Abrams Tank System', 'None', 'dc937b59892604f5a86ac96936cd7ff09e25f18ae6b758e8014a24c7fa039e91', 10, 10, null, 88, null, null, false, null),
  ('adb714e0-8ac9-52d7-9ecc-78e308ecbd8a', '3b3029e8-8048-5c9b-a9bd-b75915f5547e', 'Army', 'enlisted', '91A', null, 'assignments', 'E-1..E-4', null, 'Private, Specialist/Corporal — Critical Leader Development', 'Chapter 4. Military occupational specialty 91A M1 Abrams Tank System', 'Recovery Vehicle Operator', '8e51a96f3d583677bae071f41518086eaf811f0f82701981e76c07c5e0fe9958', 11, 11, null, 89, null, null, false, null),
