  ('7f2d3e69-4ec6-5946-9975-db06a701183c', 'd69ea188-6dea-5cf5-b1a1-3780e1f5a088', 'Army', 'enlisted', '94A', null, 'assignments', 'E-1..E-4', null, 'Private, Specialist/Corporal — Broadening developmental opportunities', 'Chapter 4. Military Occupational Specialty 94A Land Combat Electronics Missile', 'Ranger Training.', '3d013708314d682d4504c8c6c33593d90e00dc969b4b1ca1549298c25457890f', 10, 10, '10', 85, null, null, false, null),
  ('1fcb42cf-7512-5738-a3b2-b0702f049a24', 'd69ea188-6dea-5cf5-b1a1-3780e1f5a088', 'Army', 'enlisted', '94A', null, 'assignments', 'E-1..E-4', null, 'Private, Specialist/Corporal — Broadening education opportunities', 'Chapter 4. Military Occupational Specialty 94A Land Combat Electronics Missile', 'AA/AAS degree and Technician Badge.', '289bf5f7d51aeeec57bd60de77c6010c325719a9c4657bdd77d9c9c575b209d5', 10, 10, '10', 86, null, null, false, null),
  ('740b2c2e-ee39-57b7-9674-c5578b6447d9', 'd69ea188-6dea-5cf5-b1a1-3780e1f5a088', 'Army', 'enlisted', '94A', null, 'assignments', 'E-1..E-4', null, 'Private, Specialist/Corporal — Broadening training opportunities', 'Chapter 4. Military Occupational Specialty 94A Land Combat Electronics Missile', 'CompTIA Certifications, Certified Electronics Technician (CET), ETA Fiber Optics and Data Cabling Certifications, Basic Electricity and Electronics-Digital (BEE-D) Certifications, RADAR Electronics Technician (RAD), US Military Apprenticeship Program (USMAP), Culture and Language Training. Soldiers should strive to master the skills necessary to obtain certifications listed by MOS on the Army COOL website.', 'cbfdf70cbeb1f4038880a3001ecd3bc960783f0fc5db96c321b908f8dba4a029', 10, 10, '10', 87, null, null, false, null),
  ('98d08634-2255-5422-9c3b-300a147346a6', 'd69ea188-6dea-5cf5-b1a1-3780e1f5a088', 'Army', 'enlisted', '94A', null, 'development', 'E-1..E-4', null, 'Private, Specialist/Corporal — Other broadening opportunities (experiences)', 'Chapter 4. Military Occupational Specialty 94A Land Combat Electronics Missile', 'Special Missions Units (SMU).', '5a857fd8e5e6facf44074900d8eb7be574a29f01a0ed4c4874dda58b37b18552', 10, 10, '10', 88, null, null, false, null),
