  ('c057ce3a-d7e0-57d5-8bbd-ffd20a0f78bb', 'd69ea188-6dea-5cf5-b1a1-3780e1f5a088', 'Army', 'enlisted', '94A', null, 'training', 'E-5', null, 'Sergeant — Additional Training', 'Chapter 4. Military Occupational Specialty 94A Land Combat Electronics Missile', 'Airborne, Air Assault, Expert Soldier Badge, Jumpmaster, ARIMS, GCSS Army, Safety Course, Hazardous Material (HAZMAT), Modern Army Combatives Program (MACP), Tactical Combat Casualty Care (TCCC) Combat Lifesavers Course (CLS).', 'e969a6892e5653ed3f8a348d299fb218a46337ebd6188bd93e0c6d4a8f742a15', 10, 10, '10', 90, null, null, false, null),
  ('863e2140-279d-535e-ad96-6f1fa38c000e', 'd69ea188-6dea-5cf5-b1a1-3780e1f5a088', 'Army', 'enlisted', '94A', null, 'assignments', 'E-5', null, 'Sergeant — Operational assignments', 'Chapter 4. Military Occupational Specialty 94A Land Combat Electronics Missile', 'Land Combat Electronic Missile System Repairer.', '8ebace6407786d1dfbfd04bec25ac1265da7bbd215ffd6acbfc969b1bf954fd0', 10, 10, '10', 91, null, null, false, null),
  ('2cf16ca8-46cf-5ef1-90d6-055883d459f5', 'd69ea188-6dea-5cf5-b1a1-3780e1f5a088', 'Army', 'enlisted', '94A', null, 'development', 'E-5', null, 'Sergeant — Institutional assignments', 'Chapter 4. Military Occupational Specialty 94A Land Combat Electronics Missile', 'None.', '903ea500e7ccf842c1312b6c2f964e3e98ff146456cecec717e9a0e122bf735f', 10, 10, '10', 92, null, null, false, null),
